// ─── SEARCH QUERY BUILDER ─────────────────────────────────────────
// Builds search queries from the input data.
// If book_name is already known, use it; otherwise we need to fetch metadata first.

const body = $input.first().json.body || $input.first().json;

const url = body.url || '';
const platform = body.platform || 'unknown';
const lang = body.source_language || 'zh';
const bookName = body.book_name || '';
const startChapter = parseInt(body.start_chapter || 1);
const endChapter = body.end_chapter ? parseInt(body.end_chapter) : null;

// Build NovelUpdates search URL
const searchTerm = encodeURIComponent(bookName || url);
const nuSearchUrl = `https://www.novelupdates.com/?s=${searchTerm}&post_type=seriesplans`;

// Also build searches on the major aggregator sites
const fwnSearchUrl = `https://freewebnovel.com/search/?searchkey=${searchTerm}`;
const novelBinSearchUrl = `https://novelbin.com/?search=${searchTerm}`;

return [{ json: {
  original_url: url,
  platform,
  source_language: lang,
  book_name: bookName,
  start_chapter: startChapter,
  end_chapter: endChapter,
  nu_search_url: nuSearchUrl,
  fwn_search_url: fwnSearchUrl,
  novelbin_search_url: novelBinSearchUrl,
  search_term: bookName,
}}];

// ─── TRANSLATION RESULT PARSER ───────────────────────────────────
// Parses search results from all three sources.
// Ranks candidates by match quality.

const searchData = $('Code: Build Search Queries').first().json;
const bookName = (searchData.book_name || '').toLowerCase();

function stripHtml(str) {
  return (str || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function similarity(a, b) {
  a = a.toLowerCase().replace(/[^a-z0-9\s]/g, '');
  b = b.toLowerCase().replace(/[^a-z0-9\s]/g, '');
  const aWords = new Set(a.split(/\s+/));
  const bWords = new Set(b.split(/\s+/));
  const intersection = [...aWords].filter(w => bWords.has(w)).length;
  return intersection / Math.max(aWords.size, bWords.size);
}

const candidates = [];

// ── Parse NovelUpdates ──
try {
  const nuHtml = $('HTTP: Search NovelUpdates').first().json.data || '';
  // NU result format: <div class="search_main_box_nu"> ... <a class="w-blog-entry-title-h" href="...">Title</a>
  const re = /href="(https:\/\/www\.novelupdates\.com\/series\/[^"]+)"[^>]*>([^<]+)/gi;
  let m;
  while ((m = re.exec(nuHtml)) !== null) {
    const title = stripHtml(m[2]);
    const score = bookName ? similarity(title, bookName) : 0.5;
    candidates.push({
      source: 'novelupdates',
      title,
      url: m[1],
      score,
      note: 'NovelUpdates index — follow for translator site links',
    });
  }
} catch (e) {}

// ── Parse FreeWebNovel ──
try {
  const fwnHtml = $('HTTP: Search FreeWebNovel').first().json.data || '';
  const re = /href="(\/novel\/[^"]+)"[^>]*class="[^"]*book-name[^"]*"[^>]*>([^<]+)/gi;
  let m;
  while ((m = re.exec(fwnHtml)) !== null) {
    const title = stripHtml(m[2]);
    const score = bookName ? similarity(title, bookName) : 0.4;
    candidates.push({
      source: 'freewebnovel',
      title,
      url: `https://freewebnovel.com${m[1]}`,
      score,
    });
  }
  // Fallback pattern
  if (!candidates.some(c => c.source === 'freewebnovel')) {
    const re2 = /href="(\/novel\/[^"]+)"[^>]*>([^<]+)<\/a>/gi;
    while ((m = re2.exec(fwnHtml)) !== null) {
      const title = stripHtml(m[2]);
      if (title.length < 5) continue;
      const score = bookName ? similarity(title, bookName) : 0.3;
      candidates.push({ source: 'freewebnovel', title, url: `https://freewebnovel.com${m[1]}`, score });
    }
  }
} catch (e) {}

// ── Parse NovelBin ──
try {
  const nbHtml = $('HTTP: Search NovelBin').first().json.data || '';
  const re = /href="(https?:\/\/novelbin\.com\/b\/[^"]+)"[^>]*>([^<]+)/gi;
  let m;
  while ((m = re.exec(nbHtml)) !== null) {
    const title = stripHtml(m[2]);
    if (title.length < 3) continue;
    const score = bookName ? similarity(title, bookName) : 0.3;
    candidates.push({ source: 'novelbin', title, url: m[1], score });
  }
} catch (e) {}

// Sort by score desc, take top 5
candidates.sort((a, b) => b.score - a.score);
const top = candidates.slice(0, 5);

const found = top.length > 0 && top[0].score > 0.2;

return [{ json: {
  status: 'ok',
  original_url: searchData.original_url,
  original_platform: searchData.platform,
  source_language: searchData.source_language,
  book_name_searched: searchData.book_name,
  start_chapter: searchData.start_chapter,
  end_chapter: searchData.end_chapter,
  translation_found: found,
  top_candidate: found ? top[0] : null,
  all_candidates: top,
  recommended_action: found ? 'scrape_translation' : 'no_translation_found',
  recommended_url: found ? top[0].url : null,
  recommended_platform: found ? top[0].source : null,
}}];
